) AS DDJF2) AS DDJF
LEFT JOIN 
(SELECT COPTDTD001,COPTDTD002,COPTDTD003,COPTDTD004,COPTDTD005,COPTDTD006,COPTDTD008,COPTDTD009,COPTDTD010,
COPTDTD013,COPTDTD016,COPTDTD021,MOCTATA002,MOCTATA017,SUM(MOCTGTG011) AS SCSL FROM( 
SELECT COPTD.TD001 as COPTDTD001,COPTD.TD002 as COPTDTD002,COPTD.TD003 as COPTDTD003,COPTD.TD004 as COPTDTD004,COPTD.TD005 as COPTDTD005,COPTD.TD006 as COPTDTD006,COPTD.TD008 as COPTDTD008,COPTD.TD009 as COPTDTD009,COPTD.TD010 as COPTDTD010,COPTD.TD013 as COPTDTD013,COPTD.TD016 as COPTDTD016,COPTD.TD021 as COPTDTD021,
ISNULL(MOCTA.TA001,'') as MOCTATA001,ISNULL(MOCTA.TA002,'') as MOCTATA002,ISNULL(MOCTA.TA017,0) as MOCTATA017,
ISNULL(MOCTG.TG001,'') as MOCTGTG001,ISNULL(MOCTG.TG002,'') as MOCTGTG002,ISNULL(MOCTG.TG003,'') as MOCTGTG003,
ISNULL(MOCTG.TG011,0) as MOCTGTG011,ISNULL(MOCTF.TF003,'') as MOCTFTF003,ISNULL(MOCTF.TF006,'') as MOCTFTF006  
FROM ZJRD..COPTD  Left JOIN ZJRD..COPTC On COPTD.TD001=COPTC.TC001 and COPTD.TD002=COPTC.TC002 
Left JOIN ZJRD..MOCTA On COPTD.TD004=MOCTA.TA006 and COPTD.TD001=MOCTA.TA026 and COPTD.TD002=MOCTA.TA027 and COPTD.TD003=MOCTA.TA028 
Left JOIN  ZJRD..MOCTG On MOCTA.TA001=MOCTG.TG014 AND MOCTA.TA002=MOCTG.TG015 
Left JOIN ZJRD..MOCTF On MOCTG.TG001=MOCTF.TF001 AND MOCTG.TG002=MOCTF.TF002  
WHERE ((COPTD.TD013 >= '20260101' AND COPTD.TD013 <= '20260131') AND (COPTC.TC027 = 'Y')and COPTD.TD008>0)) AS DDJF

WHERE MOCTFTF003 <=CONVERT(CHAR(12),DATEADD(DAY,5,CAST(COPTDTD013 AS SMALLDATETIME)),112)
--跨月计算
GROUP BY COPTDTD001,COPTDTD002,COPTDTD003,COPTDTD004,COPTDTD005,COPTDTD006,COPTDTD008,COPTDTD009,COPTDTD010,
COPTDTD013,COPTDTD016,COPTDTD021,MOCTATA002,MOCTATA017) AS DDJF1
ON DDJF.COPTDTD001=DDJF1.COPTDTD001 AND DDJF.COPTDTD002=DDJF1.COPTDTD002 AND DDJF.COPTDTD003=DDJF1.COPTDTD003 
AND DDJF.COPTDTD004=DDJF1.COPTDTD004 AND DDJF.COPTDTD005=DDJF1.COPTDTD005 AND DDJF.COPTDTD006=DDJF1.COPTDTD006 
AND DDJF.COPTDTD008=DDJF1.COPTDTD008 AND DDJF.COPTDTD009=DDJF1.COPTDTD009 AND DDJF.COPTDTD010=DDJF1.COPTDTD010 
AND DDJF.COPTDTD013=DDJF1.COPTDTD013 AND DDJF.COPTDTD016=DDJF1.COPTDTD016 AND DDJF.COPTDTD021=DDJF1.COPTDTD021 
AND DDJF.MOCTATA002=DDJF1.MOCTATA002 AND DDJF.MOCTATA017=DDJF1.MOCTATA017



